 if(watered){ctx.fillStyle='#b8e4e6';ctx.beginPath();ctx.ellipse(p.x-28,p.y-12,3,5,-.4,0,Math.PI*2);ctx.fill()}
}
function drawCloud(x,y,scale){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#f8fbeb9c';ctx.beginPath();ctx.ellipse(0,0,39,11,0,0,Math.PI*2);ctx.ellipse(-17,-6,15,12,0,0,Math.PI*2);ctx.ellipse(1,-11,19,17,0,0,Math.PI*2);ctx.ellipse(20,-5,15,11,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawHouse(x,y,s){ctx.save();ctx.translate(x,y);ctx.fillStyle='#e8d9b8';ctx.fillRect(0,35,142,94);ctx.fillStyle='#c98765';ctx.beginPath();ctx.moveTo(-12,39);ctx.lineTo(69,-19);ctx.lineTo(154,39);ctx.closePath();ctx.fill();ctx.fillStyle='#f1e4c8';ctx.fillRect(9,53,33,27);ctx.fillRect(96,53,29,27);ctx.fillStyle='#91b6ae';ctx.fillRect(13,57,12,19);ctx.fillRect(99,57,11,19);ctx.strokeStyle='#fff0d6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(29,57);ctx.lineTo(29,76);ctx.moveTo(13,66);ctx.lineTo(39,66);ctx.moveTo(104,57);ctx.lineTo(104,76);ctx.stroke();ctx.fillStyle='#866d52';ctx.fillRect(56,76,30,53);ctx.fillStyle='#d5b786';ctx.beginPath();ctx.arc(79,101,2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8c6954';ctx.fillRect(109,4,13,35);ctx.fillStyle='#f4eddb';ctx.fillRect(-6,128,157,9);ctx.restore()}
function drawTree(x,y,s,scale){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#7b6244';ctx.fillRect(-7,-12,14,44);const season=seasonIndex();let color=['#75976c','#78915d','#b77b54','#d4e0df'][season];ctx.fillStyle=color;for(const [dx,dy,r] of [[0,-37,28],[-22,-21,23],[21,-21,24],[0,-9,25]]){ctx.beginPath();ctx.arc(dx,dy,r,0,Math.PI*2);ctx.fill()}ctx.fillStyle=['#e8c99a','#d7b462','#d7945e','#f7f7f3'][season];for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(-19+(i*17)%40,-39+(i*23)%40,2.4,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawFence(s){ctx.strokeStyle='#e7d8b7';ctx.lineWidth=8;ctx.lineCap='round';for(let i=0;i<6;i++){let x=327+i*56;ctx.beginPath();ctx.moveTo(x,321);ctx.lineTo(x,368);ctx.stroke()}ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(326,333);ctx.lineTo(607,333);ctx.moveTo(326,352);ctx.lineTo(607,352);ctx.stroke();ctx.strokeStyle='#fff0d4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(326,330);ctx.lineTo(607,330);ctx.moveTo(326,349);ctx.lineTo(607,349);ctx.stroke()}
function drawFlowers(s){let colors=['#f2dfaa','#e5b3b0','#d9c6e8','#f4e7e0'];for(let i=0;i<24;i++){let x=(i*127+53)%1000,y=350+(i*67%205);if(x>335&&x<690&&y>250&&y<440)continue;ctx.fillStyle='#58805a';ctx.fillRect(x,y,2,9);ctx.fillStyle=colors[(i+seasonIndex())%4];for(let j=0;j<4;j++){let a=j*Math.PI/2;ctx.beginPath();ctx.arc(x+Math.cos(a)*3,y+Math.sin(a)*3,2.4,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#e8c96e';ctx.beginPath();ctx.arc(x,y,1.8,0,Math.PI*2);ctx.fill()}}
function drawSign(x,y){ctx.fillStyle='#705d43';ctx.fillRect(x-3,y-14,6,39);ctx.fillStyle='#dfc99d';ctx.fillRect(x-37,y-33,74,28);ctx.strokeStyle='#a98c5d';ctx.lineWidth=2;ctx.strokeRect(x-37,y-33,74,28);ctx.fillStyle='#526650';ctx.font='bold 11px Georgia';ctx.textAlign='center';ctx.fillText('MEADOW',x,y-15);ctx.textAlign='left'}
function drawPlayer(){let p=coord(state.player.c,state.player.r);ctx.save();ctx.translate(p.x,p.y-15);ctx.fillStyle='#39473a35';ctx.beginPath();ctx.ellipse(0,18,17,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6c805f';ctx.beginPath();ctx.ellipse(0,4,11,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#edd8b9';ctx.beginPath();ctx.arc(0,-12,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#815f48';ctx.beginPath();ctx.arc(0,-16,10,Math.PI,Math.PI*2);ctx.lineTo(10,-12);ctx.quadraticCurveTo(0,-19,-10,-12);ctx.fill();ctx.fillStyle='#3d5144';ctx.beginPath();ctx.arc(3,-11,1,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#efc7a6';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-10,1);ctx.lineTo(-15,8);ctx.moveTo(10,1);ctx.lineTo(15,8);ctx.stroke();ctx.restore()}

