const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1200,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:8765/index.html');
 await page.waitForSelector('#seasonName');
 await page.screenshot({path:'/tmp/little-acre-latest.jpg',type:'jpeg',quality:82});
 const initial={day:await page.locator('#dayBadge').innerText(),season:await page.locator('#seasonName').innerText(),plots:await page.locator('canvas').count(),shop:await page.locator('[data-buy]').count()};
 await page.locator('[data-buy="turnip"]').click();
 await page.locator('[data-tool="hoe"]').click();
 const canvas=page.locator('#farm');
 async function plot(c,r){const b=await canvas.boundingBox();const x=510+(c-r)*76,y=310+(c+r)*38;await page.mouse.click(b.x+x*b.width/1000,b.y+y*b.height/565)}
 await plot(0,0);
 await page.locator('[data-tool="seed"]').click();await plot(0,0);
 await page.locator('[data-tool="water"]').click();await plot(0,0);
 await page.locator('#sleepBtn').click();
 const after={day:await page.locator('#dayBadge').innerText(),energy:await page.locator('#energyText').innerText(),saved:await page.evaluate(()=>!!localStorage.getItem('littleAcreSave')),toast:await page.locator('#toast').innerText()};
 console.log(JSON.stringify({initial,after,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
